"use client";

import * as React from "react";
import { Slider as SliderPrimitive } from "@base-ui/react/slider";

import { cn } from "@/lib/utils";
import { primaryFace, wellInset } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Paddock Slider: a thin recessed grey track. The filled part is the primary
 * Button's teal, and each knob is a white thumb with a 1px cool border and a
 * faint drop. Pass an array value for a range; the slider renders one knob per value.
 */
const Slider = React.forwardRef<
  HTMLDivElement,
  WithClassName<SliderPrimitive.Root.Props>
>(({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
  const _values = Array.isArray(value)
    ? value
    : Array.isArray(defaultValue)
      ? defaultValue
      : [min];

  return (
    <SliderPrimitive.Root
      ref={ref}
      data-slot="slider"
      thumbAlignment="edge"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      className={cn("relative w-full data-[disabled]:opacity-50", className)}
      {...props}
    >
      <SliderPrimitive.Control className="relative flex w-full touch-none select-none items-center py-1.5">
        <SliderPrimitive.Track
          data-slot="slider-track"
          className={cn("relative h-1.5 w-full grow overflow-hidden rounded-xs", wellInset)}
        >
          <SliderPrimitive.Indicator
            data-slot="slider-range"
            className={cn("rounded-md", primaryFace)}
          />
        </SliderPrimitive.Track>
        {Array.from({ length: _values.length }, (_, index) => (
          <SliderPrimitive.Thumb
            key={index}
            data-slot="slider-thumb"
            className={cn(
              "block size-4.5 cursor-grab rounded-full border border-transparent bg-card shadow-(--shadow-thumb) active:cursor-grabbing",
              "transition-transform duration-fast ease-out active:scale-95 motion-reduce:active:scale-100",
              "has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring has-[:focus-visible]:ring-offset-2 has-[:focus-visible]:ring-offset-background",
              "data-[disabled]:pointer-events-none",
            )}
          />
        ))}
      </SliderPrimitive.Control>
    </SliderPrimitive.Root>
  );
});
Slider.displayName = "Slider";

export { Slider };
